// Command build prepares the extension's generated files, the steps that
// are not npm's or vsce's own:
//
//   - dist/slides.wasm: go-slides compiled to WebAssembly (package wasm);
//   - src/gen/wasm_exec.js: the Go toolchain's JavaScript support for it,
//     copied from the toolchain that compiled it, so the two always match;
//   - media/preview.js: the Markdown preview script, go-slides' own fitting
//     script (deck.FitScript) run on every preview update.
//
// It prints the module's size raw, gzipped and brotli-compressed, and with
// --max-brotli fails when the module grows past a budget.
package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/andybalholm/brotli"
	"github.com/spf13/cobra"

	"github.com/go-slides/slides/deck"
)

// osExit allows tests to override os.Exit.
var osExit = os.Exit

func main() {
	if err := RootCmd().Execute(); err != nil {
		fmt.Fprintln(os.Stderr, "build:", err)
		osExit(1)
	}
}

type options struct {
	root      string
	goCmd     string
	skipWasm  bool
	maxBrotli int64
}

// RootCmd returns the command.
func RootCmd() *cobra.Command {
	o := &options{}
	cmd := &cobra.Command{
		Use:           "build",
		Short:         "Build the extension's WebAssembly module and generated files",
		Args:          cobra.NoArgs,
		SilenceUsage:  true,
		SilenceErrors: true,
		RunE:          func(cmd *cobra.Command, _ []string) error { return run(cmd, o) },
	}
	f := cmd.Flags()
	f.StringVar(&o.root, "root", ".", "the extension's directory")
	f.StringVar(&o.goCmd, "go", "go", "the go command that compiles the module")
	f.BoolVar(&o.skipWasm, "skip-wasm", false, "write the generated sources only, not dist/slides.wasm")
	f.Int64Var(&o.maxBrotli, "max-brotli", 0, "fail when the brotli-compressed module exceeds this many bytes (0: no budget)")
	cmd.AddCommand(&cobra.Command{
		Use:   "measure file...",
		Short: "Print files' sizes raw, gzipped and brotli-compressed",
		Args:  cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			for _, p := range args {
				b, err := os.ReadFile(p)
				if err != nil {
					return err
				}
				s := Measure(b)
				fmt.Fprintf(cmd.OutOrStdout(), "%s: %s raw, %s gzip, %s brotli\n", p, mib(s.Raw), mib(s.Gzip), mib(s.Brotli))
			}
			return nil
		},
	})
	return cmd
}

func run(cmd *cobra.Command, o *options) error {
	out := cmd.OutOrStdout()
	goroot, err := goEnv(o.goCmd, "GOROOT")
	if err != nil {
		return err
	}
	execJS, err := os.ReadFile(filepath.Join(goroot, "lib", "wasm", "wasm_exec.js"))
	if err != nil {
		return fmt.Errorf("the toolchain's wasm_exec.js: %w", err)
	}
	if err := write(filepath.Join(o.root, "src", "gen", "wasm_exec.js"), execJS); err != nil {
		return err
	}
	if err := write(filepath.Join(o.root, "media", "preview.js"), []byte(PreviewScript())); err != nil {
		return err
	}
	if o.skipWasm {
		return nil
	}
	wasm := filepath.Join(o.root, "dist", "slides.wasm")
	if err := os.MkdirAll(filepath.Dir(wasm), 0o755); err != nil {
		return err
	}
	c := exec.Command(o.goCmd, "build", "-trimpath", "-ldflags=-s -w", "-o", wasm, "./wasm")
	c.Dir = o.root
	c.Env = append(os.Environ(), "GOOS=js", "GOARCH=wasm", "CGO_ENABLED=0")
	c.Stdout, c.Stderr = cmd.OutOrStdout(), cmd.ErrOrStderr()
	if err := c.Run(); err != nil {
		return fmt.Errorf("compiling the module: %w", err)
	}
	b, err := os.ReadFile(wasm)
	if err != nil {
		return err
	}
	s := Measure(b)
	fmt.Fprintf(out, "dist/slides.wasm: %s raw, %s gzip, %s brotli\n", mib(s.Raw), mib(s.Gzip), mib(s.Brotli))
	if o.maxBrotli > 0 && s.Brotli > o.maxBrotli {
		return fmt.Errorf("the module is %d bytes brotli-compressed, over the %d budget", s.Brotli, o.maxBrotli)
	}
	return nil
}

// PreviewScript is media/preview.js. On every preview update it checks for
// a go-slides deck (#go-slides-preview); while one is shown it turns off
// VS Code's Markdown styles, which would otherwise style the slides'
// headings, code and tables on top of the theme (Marp for VS Code does the
// same), and runs go-slides' heading-fitting script (deck.FitScript).
func PreviewScript() string {
	return "// Generated by cmd/build (go-slides/vscode). Do not edit.\n" +
		"(() => {\n" +
		"  const own = (el) => el.id === 'go-slides-style' || (el.getAttribute('href') || '').includes('go-slides-preview.css') || el.closest('#go-slides-preview');\n" +
		"  const update = () => {\n" +
		"    const on = !!document.getElementById('go-slides-preview');\n" +
		"    document.body.classList.toggle('go-slides', on);\n" +
		"    for (const el of document.querySelectorAll('link[rel=\"stylesheet\"], style')) {\n" +
		"      if (!own(el)) el.disabled = on;\n" +
		"    }\n" +
		"    if (on) {\n      " + deck.FitScript + ";\n    }\n" +
		"  };\n" +
		"  window.addEventListener('vscode.markdown.updateContent', update);\n" +
		"  window.addEventListener('load', update);\n" +
		"  update();\n" +
		"})();\n"
}

// Sizes are a module's sizes in bytes.
type Sizes struct{ Raw, Gzip, Brotli int64 }

// Measure compresses b the way a server or a .vsix would: gzip at its best
// level, brotli at quality 11.
func Measure(b []byte) Sizes {
	var g bytes.Buffer
	zw, _ := gzip.NewWriterLevel(&g, gzip.BestCompression)
	zw.Write(b)
	zw.Close()
	var br bytes.Buffer
	bw := brotli.NewWriterLevel(&br, brotli.BestCompression)
	bw.Write(b)
	bw.Close()
	return Sizes{Raw: int64(len(b)), Gzip: int64(g.Len()), Brotli: int64(br.Len())}
}

func mib(n int64) string { return fmt.Sprintf("%.2f MiB", float64(n)/(1<<20)) }

func goEnv(goCmd, key string) (string, error) {
	c := exec.Command(goCmd, "env", key)
	c.Stdin = nil
	var stdout bytes.Buffer
	c.Stdout, c.Stderr = &stdout, io.Discard
	if err := c.Run(); err != nil {
		return "", fmt.Errorf("%s env %s: %w", goCmd, key, err)
	}
	v := strings.TrimSpace(stdout.String())
	if v == "" {
		return "", fmt.Errorf("%s env %s is empty", goCmd, key)
	}
	return v, nil
}

func write(path string, b []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, b, 0o644)
}
